//just like there is a transofrmation from normal coordinates to circle coordinates in 2D
//there is also      a transformation from normal coordinates to torus  coordinates in 3D
//in 2D the circle coordinates transformation can be used to create the julia fractal
//in 3D the torus  coordinates transformation can be used to create this      fractal

float pi = 3.1415926535897932384626433832795;
vec3 xyzTtor(vec3 u)
{
    vec2 v = vec2(log(length(u.xz)),u.y);
    return vec3(atan(u.z,u.x),atan(v.y,v.x),log(length(v)));
}
vec3 torTxyz(vec3 u)
{
    vec2 w = cos(u.y-vec2(0,.5)*pi)*exp(u.z);
    vec2 v = cos(u.x-vec2(0,.5)*pi)*exp(w.x);
    return vec3(v.x,w.y,v.y);
}
vec3 objec(vec3 u)
{
    vec2 m = 1.*(2.*iMouse.xy-iResolution.xy)/iResolution.y;
    vec3 n = xyzTtor(u)+vec3(m,0);
         n = torTxyz(n);
         n = vec3(m.xyx);
    if(iMouse.z<.5)
    {
        n = cos(iTime*vec3(.27,.71,.51)*4.+vec3(1,3,6))*.2;
    }
    for(float i = .5; i < 5.; ++i)
    {
        u = xyzTtor(u);    u *= vec3(2);
        u = torTxyz(u);    u = u+n;
    }
    float l = dot(u,u);
    vec3 b = abs(normalize(u));
         //b = abs(normalize(torTxyz(u)));
    vec3 c = vec3(0);
    float vol = .6;
    float a = 0.;  if(l==l && l<vol){a=max(0.,vol-l); c = b;}
    return max(1.-a*c,0.);
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 camDir = normalize(cos(iTime*vec3(.27,.71,.51)*.5+vec3(1,3,6))*vec3(9,1,9));
    //if(iMouse.z>.5){camDir = normalize(cos(iMouse.xyx/iResolution.xyx*-vec3(7,-3,7)-vec3(0,1,.5)*pi));}

    vec3 camPos = -camDir*1.9;

	vec2 uv = (2.*fragCoord.xy-iResolution.xy)/iResolution.y;
    vec3 sd = 1.5*normalize(vec3(camDir.z,0,-camDir.x));
    vec3 up = 1.5*normalize(cross(camDir,sd));
    camPos += sd*uv.x + up*uv.y;
    camPos = camPos.yxz*vec3(-1,-1,1);
    camDir = camDir.yxz*vec3(-1,-1,1);

    vec3 ray = camDir;
    vec3 p = camPos;
    vec3 c = vec3(0);                      //reflected light
    vec3 g = vec3(1.4);                    //directed light
    for (int i = 0; i < 333; ++i)          //ray march
    {
        vec3 r = objec(p);
        vec3 g2 = g;
        g *= r;
        c += g*r*(g2-g);
        p += ray*3./333.;
    }
	fragColor = vec4(c,0);
}
